package com.enterprise.procurement.persistence.entity;
import com.baomidou.mybatisplus.annotation.*; import java.time.LocalDateTime;
@TableName("inventory_transaction") public class InventoryTransactionEntity { @TableId(type=IdType.AUTO) private Long id; private Long productId; private String type; private Integer quantity; private String referenceNo; private Long operatorId; private LocalDateTime createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getProductId(){return productId;} public void setProductId(Long v){productId=v;} public String getType(){return type;} public void setType(String v){type=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public String getReferenceNo(){return referenceNo;} public void setReferenceNo(String v){referenceNo=v;} public Long getOperatorId(){return operatorId;} public void setOperatorId(Long v){operatorId=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
